import {NAMES,COLORS,CASINOS,EFFECTS,SPECIALS,MINIGAMES,SKILLS,canSkill,useSkill,botSkill,isHuman,miniAction,miniBotAction,sum,createGame,nextRound,rollDice,placeDice,skipTurn,canSkip,outcome,previewTable,botChoice,botShouldSkip,winners,validSave} from './core.mjs';
import {createCinema} from './cinema.mjs';
import {createTutorial} from './tutorial.mjs';
import {createClaimFeedback,claimMarkup} from './claims.mjs';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const SAVE='vegas-night-save-v5',PREF='vegas-night-prefs-v2';
const read=k=>{try{return JSON.parse(localStorage.getItem(k))}catch{return null}};
const write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}};
const ART=['denim-final.png','cowboy-final.png','owner-final.png','bunny-final.png'];
const HEIGHT=[.87,.98,1,.94],LABEL=['短裤女士','筹码牛仔','赌场老板','兔女郎'];
const SYMBOL=['◆','●','■','▲'],MODE={half:'1–3 特殊赌场',all:'六座全部特殊',classic:'六座经典赌场'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>`${n/10000}万`,awardFor=(o,i)=>sum(o.awards.filter(a=>a.player===i).map(a=>a.amount));
const dots={1:[4],2:[0,8],3:[0,4,8],4:[0,2,6,8],5:[0,2,4,6,8],6:[0,2,3,5,6,8]};
function die(n){return `<span class="die" aria-hidden="true">${Array.from({length:9},(_,i)=>`<i class="${dots[n].includes(i)?'':'off'}"></i>`).join('')}</span>`;}
let prefs={sound:true,fast:false,motion:true,cutins:true,...read(PREF)},saved=read(SAVE),game=validSave(saved)?saved:null;
let skillActor=1,skillTarget=null,skillFace=null,skillZone=null,skillIndex=null;
let chosenHero=game?.hero||0,selected=0,busy=false,timer=0,generation=0,audio,dialogType='',preview=false,storageOK=true;
let passiveRound=game?.round||0;
const cinema=createCinema({names:NAMES,colors:COLORS,skills:SKILLS,die,prefs:()=>prefs});
const claimFeedback=createClaimFeedback({prefs:()=>prefs,hero:()=>game?.hero??1});
const tutorial=createTutorial({cinema,die,prefs:()=>prefs,onExit:()=>{app.inert=false;chosenHero=1;welcome();}});
function startTutorial(){claimFeedback.clear();stopTimer();if(modal.open)modal.close();dialogType='';app.inert=true;tutorial.open();}
function sound(kind){if(!prefs.sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const fs=kind==='roll'?[160,250,190,310]:kind==='win'?[523,659,784]:kind==='skip'?[350,250]:kind==='tie'?[220,185]:[460,640];fs.forEach((f,i)=>{const o=audio.createOscillator(),v=audio.createGain(),t=audio.currentTime+i*.075;o.type=kind==='roll'?'triangle':'sine';o.frequency.setValueAtTime(f,t);v.gain.setValueAtTime(.001,t);v.gain.linearRampToValueAtTime(.05,t+.007);v.gain.exponentialRampToValueAtTime(.001,t+.13);o.connect(v);v.connect(audio.destination);o.start(t);o.stop(t+.15);});}catch{}}
function persist(){if(game&&!preview&&!tutorial.active)storageOK=write(SAVE,game);}
function human(){return isHuman(game);}
function canAct(){return game&&!preview&&!busy&&!cinema.active&&!modal.open&&human();}
function announce(s){$('#announce').textContent=s;}
function portrait(i,extra=''){return `<img class="character-art ${extra}" src="./assets/${ART[i]}" alt="${LABEL[i]}" style="--height:${HEIGHT[i]}" draggable="false">`;}
function seat(i){const change=game.lastEvent?.changes.find(x=>x.player===i)?.delta||0,tied=game.lastEvent?.ties.includes(i),reaction=tied?'撞数了！得换个打法。':change>0?['这笔奖金，我先占着。','筹码站在我这边。','今晚的账，很漂亮。','谢谢，这张先归我啦。'][i]:change<0?['等等，我的奖金呢？','这局还没结束。','有意思，再算一遍。','别急，我会拿回来的。'][i]:'';const p=game.players[i],active=i===game.turn&&!['settled','finished'].includes(game.phase);return `<section class="seat ${active?'active':''} seat-${i}" style="--pc:${COLORS[i]}"><div class="seat-top"><span>${SYMBOL[i]} ${isHuman(game,i)?(i===game.hero?'你':'玩家'):'电脑'}</span><span>${active?'正在行动':p.left?'等待出手':'本轮完成'}</span></div><button class="portrait-button" data-character="${i}" aria-label="查看${LABEL[i]}立绘">${portrait(i)}</button>${reaction?`<div class="reaction">${reaction}</div>`:''}<div class="seat-caption"><h2>${esc(p.name)}</h2><div class="seat-stats"><strong>${money(p.cash)}</strong><span>剩 <b>${p.left}</b> 颗骰子</span><em class="chip-count">◉ ${p.chips} 筹码</em></div></div></section>`;}
function table(t,i,choosing,done){
  const n=game.roll.filter(x=>x===i+1).length,active=choosing&&n>0,staged=selected===i+1&&choosing,v=staged?previewTable(game,i+1):t,o=outcome(v),fx=EFFECTS[t.effect];
  const claims=[...o.awards];
  let forecast=staged?`预览：${o.ties.includes(game.turn)?'撞数，暂时出局':awardFor(o,game.turn)?`可拿 ${money(awardFor(o,game.turn))}`:'暂时拿不到钱'}`:o.ties.length?`${o.ties.map(j=>SYMBOL[j]).join(' ')} 撞数出局`:o.awards.length?`${SYMBOL[o.awards[0].player]} ${done?'获得':'暂领'} ${money(awardFor(o,o.awards[0].player))}`:active?`可放 ${n} 颗 · 点击预览`:'等待入桌';
  return `<article class="casino casino-${i+1} ${active?'available':''} ${staged?'selected':''} ${t.effect!=='classic'?'special':''}"><button class="table-target" data-face="${i+1}" ${active?'':'disabled'} aria-label="${i+1}号${t.name}，总奖金${money(sum(t.notes))}，${active?`放入${n}颗`:'当前不可放置'}"><div class="casino-head"><span class="face">${die(i+1)}</span><div><h3>${t.name}</h3><div class="casino-total">总额 <strong>${money(sum(t.notes))}</strong></div></div></div><div class="banknotes" aria-label="${t.notes.map(money).join('、')}">${t.notes.map((value,noteIndex)=>{const k=claims.findIndex(a=>a.amount===value),a=k<0?null:claims.splice(k,1)[0];return `<span data-note="${noteIndex}" data-owner="${a?a.player:'none'}" style="--owner:${a?COLORS[a.player]:'#dec98d'}">${money(value)}<small>${a?(a.player===game.hero?'你':['丹宁','牛仔','老板','月兔'][a.player])+(done?' 获得':' 暂领'):'待分配'}</small></span>`;}).join('')}</div><div class="counts">${v.counts.map((c,j)=>`<span data-player="${j}" style="--pc:${COLORS[j]}" class="pile ${c?'':'empty'} ${o.ties.includes(j)?'tied':''}" title="${esc(game.players[j].name)}：${c}颗骰子，加成${v.bonus[j]}，合计${c+v.bonus[j]}"><small>${SYMBOL[j]}</small>${c?c+(v.bonus[j]?'+'+v.bonus[j]:''):'–'}</span>`).join('')}</div><div class="forecast">${forecast}${staged&&MINIGAMES.includes(t.effect)&&!t.played[game.turn]?' · 小游戏加成待定':''}</div></button><button class="effect" data-info="${i+1}" aria-label="查看${i+1}号赌场规则：${fx.name}"><span>${t.effect!=='classic'?'✦':'◇'} ${fx.name}</span><span>ⓘ</span></button></article>`;
}
function abilityBar(){return game.skills?`<section class="ability-bar" aria-label="角色技能"><span>✦ 角色技能版</span>${game.players.map((p,i)=>`<button data-skill="${i}" style="--pc:${COLORS[i]}" ${preview?'disabled':''}><b>${SYMBOL[i]} ${SKILLS[i].name}</b><small>${i===0?'被动 · 每轮9骰':p.used?'本轮已用':isHuman(game,i)?'点击发动':'电脑 · 尚未发动'}</small></button>`).join('')}</section>`:'';}
function render(){
  document.documentElement.classList.toggle('no-motion',!prefs.motion);
  const g=game,done=['settled','finished'].includes(g.phase),choosing=g.phase==='choose'&&human()&&!busy&&!preview,total=sum(g.tables.flatMap(t=>t.notes));
  const current=selected?g.tables[selected-1]:null;
  app.innerHTML=`<main class="shell"><header class="top"><div class="brand"><span class="brand-mark">V</span><div><div class="eyebrow">VEGAS AFTER DARK</div><h1>拉斯维加斯 <span>· 骰子之夜</span></h1></div></div><nav class="tools" aria-label="游戏菜单"><button class="quiet" data-action="tutorial">教学</button><button class="quiet" data-action="rules">玩法</button><button class="quiet" data-action="settings">${prefs.sound?'声音 · 开':'声音 · 关'}</button><button class="quiet" data-action="pause">暂停</button></nav></header>
  <div class="roundbar"><div class="rounds"><span>第 <strong>${g.round}</strong> / 4 轮</span>${[1,2,3,4].map(n=>`<i class="${n<=g.round?'on':''}"></i>`).join('')}</div><span class="mode-tag">${MODE[g.rules]} · ${g.skills?'技能版':'普通版'}</span><span class="sort-hint">每桌2张 · 1 → 6 总额递增</span></div>
  <div class="game-scene"><aside class="cast-rail left-rail" aria-label="左侧玩家">${seat(0)}${seat(2)}</aside><section class="arena" aria-label="顺时针排列的六座赌场"><div class="orbit" aria-hidden="true"></div>${g.tables.map((t,i)=>table(t,i,choosing,done)).join('')}<div class="table-center"><div class="center-star">✧</div><span class="eyebrow">${current?'CASINO '+current.face:'TONIGHT’S POT'}</span><div class="pot">${current?current.name:money(total)}</div><p>${current?EFFECTS[current.effect].short:'六座赌场 · 各凭本事'}</p><div class="center-turn" style="--pc:${COLORS[g.turn]}">${done?'本轮下注结束':`${SYMBOL[g.turn]} ${esc(g.players[g.turn].name)}`}</div><small>${done?'查看下方结算':busy?'骰子正在落定':g.phase==='choose'?'选点下注，或跳过等下次':'准备掷骰'}</small></div></section><aside class="cast-rail right-rail" aria-label="右侧玩家">${seat(1)}${seat(3)}</aside></div>
  ${abilityBar()}<section class="control" aria-label="当前回合"><div class="roll-area"><div class="turntitle">${done?'本轮筹码已落定':busy?'骰子正在落定…':human()?`轮到<span style="color:${COLORS[g.turn]}">${esc(g.players[g.turn].name)}</span>`:`${esc(g.players[g.turn].name)}正在考虑…`}</div><div class="turnhint">${done?'逐桌查看特殊效果和奖金归属。':g.phase==='choose'?selected?`选择 ${selected} 点的 ${g.roll.filter(x=>x===selected).length} 颗，一起放进${CASINOS[selected-1]}。`:'不满意可支付1筹码跳过：不下注、留骰，等下次轮到自己再掷。':`掷出剩余 ${g.players[g.turn].left} 颗骰子，选择一种点数下注。`}</div><div class="dice-row ${busy?'rolling':''}" aria-label="本次骰子">${g.roll.length?[...g.roll].sort((a,b)=>a-b).map(n=>`<button class="dicebutton ${selected===n?'picked':''}" data-face="${n}" ${choosing?'':'disabled'} aria-label="选择${n}点">${die(n)}</button>`).join(''):Array.from({length:Math.min(g.players[g.turn].left,9)},()=>'<span class="emptydie" aria-hidden="true">·</span>').join('')}</div></div><div class="actionarea"><button class="primary" data-action="${done?'summary':g.phase==='choose'?'confirm':'roll'}" ${done?'':!human()||busy||preview||(g.phase==='choose'&&!selected)?'disabled':''}>${done?'查看结算':busy?'掷骰中…':!human()?'等待对手':g.phase==='choose'?selected?`放入 ${g.roll.filter(x=>x===selected).length} 颗 →`:'先选一种点数':'掷骰子'}</button>${!done?`<button class="skip" data-action="skip" ${choosing&&canSkip(g)?'':'disabled'}>${g.players[g.turn].chips?'支付1筹码 · 跳过本次':'筹码不足 · 无法跳过'}</button>`:''}<div class="keyhint">空格掷骰 · 1–6 选点 · Enter 确认 · S 跳过</div></div></section>
  <div class="claim-inline">${preview?'':claimMarkup(g.lastEvent,g.hero,{settled:done,compact:true})}</div><div class="table-log" aria-label="牌桌动态"><span>牌桌动态</span><p>${esc(g.history[0]||'等待开局')}</p><button data-action="history" class="text-button">查看记录</button></div><footer><span>${g.humans===1?'你与三位电脑':g.humans===4?'四人同屏轮流':'两人同屏 + 两位电脑'} · ${storageOK?'本机自动保存':'本机无法保存进度'}</span><span>自定义规则版 · 无真实金钱交易</span></footer></main>`;
}
function stopTimer(){clearTimeout(timer);generation++;}
function captureSkill(actor,choice){const target=choice.target,t=game.tables[(choice.face||1)-1],p=game.players[actor],other=game.players[target];return {actor,target,face:choice.face,zone:choice.zone,value:choice.zone==='roll'?game.roll[choice.index]:choice.face, before:choice.zone==='table'?t.counts[target]:other.left,a:t.counts[actor],b:t.counts[target],chips:p.chips,cash:p.cash,human:isHuman(game,actor)};}
function playSkillEvent(event,done){stopTimer();busy=false;if(modal.open)modal.close();dialogType='';render();cinema.play('skill',event,()=>{render();cinema.tablePulse(event);if(!event.demo&&event.actor!==0)claimFeedback.play(game.lastEvent,{settled:['settled','finished'].includes(game.phase)});done();});}
function resumeFlow(){if(['settled','finished'].includes(game.phase))showSummary();else scheduleBot();}
function resolveBotSkills(){if(cinema.active)return true;if(!game.skills||preview)return false;for(const i of [1,2,3]){if(isHuman(game,i))continue;const choice=botSkill(game,i);if(!choice)continue;const event=captureSkill(i,choice);if(useSkill(game,i,choice)){event.after=event.before-1;event.amount=game.players[i].cash-event.cash;event.label=game.history[0];persist();selected=0;playSkillEvent(event,resumeFlow);return true;}}return false;}
function scheduleBot(){clearTimeout(timer);if(tutorial.active)return;if(claimFeedback.remaining){timer=setTimeout(scheduleBot,claimFeedback.remaining);return;}if(cinema.active)return;if(!preview&&!modal.open&&!document.hidden&&!busy){if(game.skills&&passiveRound!==game.round){passiveRound=game.round;playSkillEvent({actor:0,human:isHuman(game,0)},resumeFlow);return;}if(resolveBotSkills())return;}if(game?.phase==='minigame'&&!preview&&!modal.open&&!document.hidden){showMini();return;}if(!game||preview||human()||modal.open||document.hidden||busy||!['ready','choose'].includes(game.phase))return;timer=setTimeout(()=>{if(modal.open||document.hidden)return;if(game.phase==='ready')doRoll();else if(botShouldSkip(game))doSkip();else{selected=botChoice(game);render();timer=setTimeout(()=>{if(!modal.open&&!document.hidden)commit();},prefs.fast?100:700);}},prefs.fast?120:650);}
function doRoll(){if(busy||cinema.active||modal.open||game.phase!=='ready')return;stopTimer();rollDice(game);const actor=game.turn,values=[...game.roll];selected=0;busy=true;render();persist();cinema.play('roll',{actor,values},()=>{busy=false;render();announce(`${game.players[actor].name}掷出${values.join('、')}`);scheduleBot();});}
function commit(){if(!selected||game.phase!=='choose'||busy||modal.open)return;const actor=game.turn,face=selected,count=game.roll.filter(n=>n===face).length;cinema.flyDice(face,count,actor);if(!placeDice(game,face))return;selected=0;persist();if(outcome(game.tables[face-1]).ties.includes(actor))sound('tie');render();claimFeedback.play(game.lastEvent,{settled:['settled','finished'].includes(game.phase)});announce(game.history[0]);if(['settled','finished'].includes(game.phase))timer=setTimeout(showSummary,Math.max(claimFeedback.remaining,prefs.fast?100:650));else scheduleBot();}
function doSkip(){if(busy||modal.open||!canSkip(game))return;stopTimer();skipTurn(game);selected=0;persist();cinema.sample('chips');sound('skip');render();announce(game.history[0]);scheduleBot();}
function openDialog(type,html){stopTimer();busy=false;dialogType=type;modal.className=type;modal.innerHTML=html;if(!modal.open)modal.showModal();render();}
function closeDialog(){modal.close();dialogType='';scheduleBot();}
function welcome(){claimFeedback.clear();if(!game){game=createGame();preview=true;}render();openDialog('welcome',`<div class="welcome-heading"><div class="eyebrow">VEGAS AFTER DARK</div><h2>今晚，谁把奖金带走？</h2><p>先选一位角色，今晚由你入座。</p></div><button class="tutorial-entry" data-action="tutorial"><span><b>序章 · 霓虹下的第一局</b><small>扮演牛仔 · 月兔逐步带你操作 · 约4分钟 · 可中途退出续学</small></span><span>进入教学 ↗</span></button><div class="cast-lineup">${[0,1,2,3].map(i=>`<button class="cast-member role-choice" data-pick="${i}" aria-pressed="${i===chosenHero}" style="--pc:${COLORS[i]};--height:${HEIGHT[i]}">${portrait(i)}<span>${LABEL[i]}</span><small>${i===chosenHero?'✓ 你已选择':'选择角色'}</small></button>`).join('')}</div><p class="role-note" id="role-description">技能版 · ${SKILLS[chosenHero].name}：${SKILLS[chosenHero].text}</p><p class="role-note">双人模式由所选角色及下一位入座，四人模式全部由玩家操作。</p><div class="setup"><label>今晚和谁玩？<select id="mode"><option value="1">独自练手 · 你 + 3 位电脑</option><option value="2">两人同屏 + 2 位电脑</option><option value="4">四位朋友 · 同屏轮流</option></select></label><label>牌局版本<select id="edition"><option value="skills">角色技能版 · 四位专属技能</option><option value="normal">普通版 · 无角色技能</option></select></label><label>赌场规则<select id="ruleset"><option value="half">1–3 随机特殊 · 4–6 经典</option><option value="all">六座全部随机特殊</option><option value="classic">六座全部经典</option></select></label></div><div class="welcome-actions"><button class="primary" data-action="start">入座，开一局</button>${!preview?'<button class="quiet" data-action="resume">继续上次牌局</button>':''}</div><p class="welcome-note">每轮发2枚筹码，剩余可累计；支付1枚跳过本次，下次轮到自己重投。<br>4 轮定胜负 · 暂不支持远程联机</p>`);}
function showRules(){openDialog('rules',`<div class="eyebrow">TABLE RULES</div><h2>怎么玩</h2><div class="steps"><p><b>掷骰与下注</b>每人每轮8颗（技能版短裤女士9颗），掷出所有剩余骰子，选一种点数，把该点数全部骰子放进对应赌场。</p><p><b>跳过与重投</b>掷完不满意，支付1枚筹码跳过本次，不选骰、不下注，骰子全部保留。每轮发2枚筹码，剩余可累计；筹码不足时不能跳过。下一位先行动，再轮到你时重投。若只剩你有骰子，会立即再次轮到你。</p><p><b>奖金与胜负</b>每大轮每座赌场固定发两张钞票，按两张合计从小到大分配到1–6号；同总额允许并列。所有人放完才结算，四轮奖金最多者获胜；同额比钞票张数，再同则共享胜利。</p></div><p><b>特殊效果</b>每大轮从${SPECIALS.length}种效果中随机抽取、不重复分配。默认只给1–3号，4–6号保持经典；全特殊模式给六座都抽取。本轮下注期间效果不变。特殊模式的1–3号中至少有一个小游戏桌。</p><p><b>入桌小游戏</b>每人每轮首次向小游戏桌下注时触发；加成只在该桌计入排名和撞数，不增加手中骰子，也不额外发钱。</p>${game.skills?`<h3>角色技能 · 每轮重置</h3><div class="rule-list">${SKILLS.map((x,i)=>`<div><b>${NAMES[i]} · ${x.name}</b><p>${x.text}</p></div>`).join('')}</div>`:''}<h3>当前：${MODE[game.rules]}</h3><div class="rule-list">${game.tables.map(t=>`<div><b>${t.face} · ${t.name} — ${EFFECTS[t.effect].name}</b><p>${EFFECTS[t.effect].text}</p></div>`).join('')}</div><p class="fineprint">特殊赌场为本版自定义设计，不是官方扩展复刻。基础桌游机制：Rüdiger Dorn。<a href="https://www.ravensburger.org/spielanleitungen/ecm/Spielanleitungen/26938_Vegas_EN.pdf" target="_blank" rel="noreferrer">经典规则 ↗</a></p><button class="primary" data-action="close">明白了，回到牌桌</button>`);}
function showInfo(face){const t=game.tables[face-1],fx=EFFECTS[t.effect];openDialog('info',`<div class="eyebrow">CASINO ${face}</div><h2>${t.name} · ${fx.name}</h2><p>${fx.text}</p><div class="info-money">本桌总奖金 <strong>${money(sum(t.notes))}</strong><span>${t.notes.map(money).join(' + ')}</span></div><p class="fineprint">排序与撞数均按本桌规则处理；预览只是当前局面，别人之后仍可改变它。</p><button class="primary" data-action="close">回到牌桌</button>`);}
function showMini(){
 if(cinema.active)return;const p=game.pending;if(!p)return;const bot=!human(),done=p.stage==='done',black=p.kind==='blackjack',earned=black?(p.total>=19?2:p.total>=16?1:0):p.wins;
 openDialog('minigame',`<div class="eyebrow">CASINO ${p.face} · ${esc(game.players[p.actor].name)}</div><h2>${EFFECTS[p.kind].name}</h2><p>${black?'从12点起步：16–18点加1，19–21点加2，超过21点归零。':'猜下一颗骰子更大或更小，相同算输。猜对一次可收手，再猜对一次加2。'}</p><div class="mini-total">${black?p.total:die(p.total)}<small>${black?'当前点数':'当前基准骰子'}</small></div><div class="mini-draws">${p.draws.map(die).join('')}</div><div class="claim-inline">${claimMarkup(game.lastEvent,game.hero,{compact:true})}</div><p class="mini-message">${esc(p.message)||'加成会改变本桌排名，也可能撞数。'}</p><div class="mini-actions">${done?`<strong>本桌加成 +${p.earned}</strong><button class="primary" data-mini="continue" ${bot?'disabled':''}>${bot?'对手即将结束':'完成，回到牌桌'}</button>`:black?`<button class="primary" data-mini="draw" ${bot?'disabled':''}>再掷一颗</button><button class="quiet" data-mini="bank" ${bot?'disabled':''}>收手 · 加成 +${earned}</button>`:`<button class="primary" data-mini="higher" ${bot?'disabled':''}>猜更大 · ${6-p.total}/6</button><button class="primary" data-mini="lower" ${bot?'disabled':''}>猜更小 · ${p.total-1}/6</button><button class="quiet" data-mini="bank" ${bot?'disabled':''}>${p.wins?'收手 · 加成 +1':'放弃挑战 · 加成 +0'}</button>`}</div><p class="fineprint">${bot?'电脑正在选择…':'你的下注已放入赌场，小游戏不消耗手中骰子。'}</p>${skillLinks()}<button class="text-button" data-action="mini-pause">暂停</button>`);
 if(bot&&!document.hidden)timer=setTimeout(()=>applyMini(miniBotAction(game)),prefs.fast?100:850);
}
function applyMini(action){const previousClaim=game.lastEvent;if(!miniAction(game,action))return;persist();sound(action==='draw'?'roll':'place');if(game.phase==='minigame')showMini();else{closeDialog();render();if(['settled','finished'].includes(game.phase))timer=setTimeout(showSummary,prefs.fast?100:650);}if(game.lastEvent!==previousClaim)claimFeedback.play(game.lastEvent,{toast:!modal.open});}

function skillLinks(){return game.skills?'<div class="skill-links">'+[1,2,3].filter(i=>isHuman(game,i)&&canSkill(game,i)).map(i=>`<button class="quiet" data-skill="${i}">发动 · ${SKILLS[i].name}</button>`).join('')+'</div>':'';}
function showSkill(actor,keep=false){
 if(!game.skills)return;if(!keep){skillActor=actor;skillTarget=null;skillZone=null;skillFace=null;skillIndex=null;}
 const p=game.players[actor],allowed=isHuman(game,actor)&&canSkill(game,actor),targets=game.players.map((p,i)=>({p,i})).filter(x=>actor===1||x.i!==actor);
 let content='';
 if(allowed){content=`<h3>选择目标</h3><div class="skill-targets">${targets.map(({p,i})=>`<button data-target="${i}" aria-pressed="${i===skillTarget}" ${actor===3&&!p.wallet.length?'disabled':''} style="--pc:${COLORS[i]}">${SYMBOL[i]} ${esc(p.name)}<small>${p.left}骰 · ${p.chips}筹码 · ${p.notes}张钱</small></button>`).join('')}</div>`;
 if(skillTarget!==null){const target=game.players[skillTarget];
 if(actor===3)content+=`<div class="draw-wallet">${Array.from({length:Math.min(target.notes,12)},()=>'<i>？</i>').join('')}</div><p>从${target.notes}张钞票中等概率抽取一张。</p>`;
 else{const options=[];
 if(actor===1&&target.left){if(game.phase==='choose'&&game.turn===skillTarget)game.roll.forEach((n,i)=>options.push(`<button data-skillzone="roll" data-skillindex="${i}" aria-pressed="${skillZone==='roll'&&skillIndex===i}">${die(n)}<small>刚掷出 · 第${i+1}颗</small></button>`));else options.push(`<button data-skillzone="hand" aria-pressed="${skillZone==='hand'}">手中骰子<small>尚未掷出 · 剩${target.left}颗</small></button>`);}
 game.tables.forEach(t=>{if(actor===1?!t.counts[skillTarget]:t.counts[actor]===t.counts[skillTarget])return;options.push(`<button data-skillzone="table" data-skillface="${t.face}" aria-pressed="${skillZone==='table'&&skillFace===t.face}">${t.face}号 · ${t.name}<small>${actor===1?'目标 '+t.counts[skillTarget]+'颗':'你 '+t.counts[actor]+'颗 ↔ 对方 '+t.counts[skillTarget]+'颗'}</small></button>`);});
 content+='<h3>'+ (actor===1?'选择要狙掉的一颗':'选择交换的赌场')+'</h3><div class="skill-options">'+options.join('')+'</div>';
 if(!options.length)content+='<p>此目标当前没有可以操作的骰子。</p>';
 if(actor===2)content+=`<p>这次交易会将你的全部 <b>${p.chips}</b> 枚筹码交给${esc(target.name)}。</p>`;
 }
 const ready=actor===3?target.wallet.length>0:skillZone!==null;
 content+=`<button class="primary" data-action="skill-confirm" ${ready?'':'disabled'}>${actor===1?'确认狙击':actor===2?'交出全部筹码，强制交易':'随机抽走一张'}</button>`;
 }}else content=`<p>${actor===0?'初来乍到已生效：每轮9颗骰子。':p.used?'本轮技能已经发动过，下轮恢复。':!isHuman(game,actor)?'这位角色由电脑操作。':actor===2&&!p.chips?'筹码不足，交易至少需要1枚。':'本轮已结算，不能再改变赌场骰子。'}</p>`;
 openDialog('skill',`<div class="eyebrow">${esc(p.name)} · ROUND ${game.round}</div><h2>${SKILLS[actor].name}</h2><p>${SKILLS[actor].text}</p>${content}<button class="quiet" data-action="skill-close">返回牌桌</button>`);
}
function confirmSkill(){
 if(cinema.active||!isHuman(game,skillActor))return;const choice={target:skillTarget,zone:skillZone,face:skillFace,index:skillIndex},event=captureSkill(skillActor,choice);
 if(!useSkill(game,skillActor,choice))return;event.after=event.before-1;event.amount=game.players[skillActor].cash-event.cash;event.label=game.history[0];const message=game.history[0],actor=skillActor;
 selected=0;persist();playSkillEvent(event,()=>openDialog('skill-result',`<div class="eyebrow">ABILITY ACTIVATED</div><h2>${SKILLS[actor].name} · 已发动</h2><p>${esc(message)}</p>${claimMarkup(game.lastEvent,game.hero,{compact:true})}<p class="fineprint">本轮技能已使用，下轮恢复。</p><button class="primary" data-action="skill-close">继续牌局</button>`));
}
function previewCinema(actor){const demo={actor,target:actor===3?2:0,face:3,zone:'table',value:3,before:4,after:3,a:1,b:4,chips:2,amount:50000,human:true,demo:true,label:'仅预览演出 · 不消耗技能和筹码'};playSkillEvent(demo,showSettings);}
function showSettings(){openDialog('settings',`<div class="eyebrow">SETTINGS</div><h2>按你的节奏来</h2><label class="settingsrow">骰子与结算音效<input type="checkbox" data-pref="sound" ${prefs.sound?'checked':''}></label><label class="settingsrow">加快电脑出手<input type="checkbox" data-pref="fast" ${prefs.fast?'checked':''}></label><label class="settingsrow">技能特写演出<input type="checkbox" data-pref="cutins" ${prefs.cutins?'checked':''}></label><label class="settingsrow">动态演出与掷骰动画<input type="checkbox" data-pref="motion" ${prefs.motion?'checked':''}></label><h3>演出试映</h3><div class="cinema-demo-buttons">${SKILLS.map((x,i)=>`<button data-preview="${i}">${x.name}</button>`).join('')}</div><p class="fineprint">预览不改变牌局。演出可随时跳过；系统减少动态效果时自动简化。</p><button class="text-button" data-action="credits">素材与制作</button><button class="primary" data-action="close">回到牌桌</button>`);}
function showPause(){openDialog('pause',`<div class="eyebrow">TAKE YOUR TIME</div><h2>牌桌暂停了</h2><p>${storageOK?'当前进度已保存在这台设备。':'当前浏览器无法保存进度，请保持页面打开。'}</p><button class="primary" data-action="close">继续牌局</button><button class="quiet" data-action="tutorial">跟月兔重温教学</button><button class="quiet" data-action="restart-prompt">重新开一桌</button>`);}
function showSummary(){if(!['settled','finished'].includes(game.phase))return;if(resolveBotSkills())return;const gains=[0,0,0,0];game.settlements.forEach(o=>o.awards.forEach(a=>gains[a.player]+=a.amount));const final=game.phase==='finished',win=final?winners(game):[];sound('win');openDialog('summary',`<div class="eyebrow">${final?'THE FINAL COUNT':`ROUND ${game.round} · PAYOUT`}</div><h2>${final?`${win.map(i=>esc(game.players[i].name)).join('、')}${win.length>1?'并列获胜':'赢下牌局'}`:`第 ${game.round} 轮结算`}</h2><p>${final?'四轮结束。奖金相同按钞票张数排名。':'以下为本轮赌场派彩；技能造成的钱款变化已计入当前总额。'}</p><div class="claim-inline">${claimMarkup(game.lastEvent,game.hero,{settled:true,compact:true})}</div><div class="resultrows">${game.players.map((p,i)=>({p,i})).sort((a,b)=>final?b.p.cash-a.p.cash||b.p.notes-a.p.notes:gains[b.i]-gains[a.i]).map(({p,i})=>`<div class="resultrow"><span style="color:${COLORS[i]}">${win.includes(i)?'✦ ':''}${esc(p.name)}${final?` <small>· ${p.notes}张钞票</small>`:''}</span><strong>${final?money(p.cash):'+'+money(gains[i])}${final?'':`<small style="display:block">现有 ${money(p.cash)}</small>`}</strong></div>`).join('')}</div><div class="summarytable">${game.tables.map((t,i)=>{const o=game.settlements[i],recipients=[...new Set(o.awards.map(a=>a.player))];return `<div class="summaryline"><b>${i+1} · ${t.name}</b><span>${EFFECTS[t.effect].name}</span><p>${recipients.length?recipients.map(j=>`${esc(game.players[j].name)} +${money(awardFor(o,j))}`).join(' / '):'无人获得奖金'}</p>${o.ties.length?`<small>撞数出局：${o.ties.map(j=>esc(game.players[j].name)).join('、')}</small>`:''}</div>`}).join('')}</div>${skillLinks()}<button class="primary" data-action="${final?'again':'next'}">${final?'再来一局':`进入第 ${game.round+1} 轮`}</button><button class="quiet" data-action="close">查看牌桌</button>`);}
app.addEventListener('click',e=>{if(cinema.active)return;const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.skill!==undefined){showSkill(Number(b.dataset.skill));return;}if(b.dataset.face){if(canAct()&&game.phase==='choose'){selected=Number(b.dataset.face);render();}return;}if(b.dataset.info){showInfo(Number(b.dataset.info));return;}if(b.dataset.character!==undefined){const i=Number(b.dataset.character);openDialog('character',`<h2>${LABEL[i]}</h2>${portrait(i)}<button class="primary" data-action="close">回到牌桌</button>`);return;}const a=b.dataset.action;if(a==='tutorial'){startTutorial();return;}if(a==='rules')showRules();if(a==='settings')showSettings();if(a==='pause')showPause();if(a==='summary')showSummary();if(a==='roll'&&canAct())doRoll();if(a==='confirm'&&canAct())commit();if(a==='skip'&&canAct())doSkip();if(a==='history')openDialog('history',`<h2>牌桌记录</h2><div class="history-list">${game.history.map(s=>`<p>${esc(s)}</p>`).join('')}</div><button class="primary" data-action="close">回到牌桌</button>`);});
modal.addEventListener('click',e=>{if(cinema.active)return;const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.preview!==undefined){previewCinema(Number(b.dataset.preview));return;}if(b.dataset.skill!==undefined){showSkill(Number(b.dataset.skill));return;}if(b.dataset.target!==undefined){skillTarget=Number(b.dataset.target);skillFace=null;skillZone=null;showSkill(skillActor,true);return;}if(b.dataset.skillzone){skillZone=b.dataset.skillzone;skillFace=b.dataset.skillface?Number(b.dataset.skillface):null;skillIndex=b.dataset.skillindex!==undefined?Number(b.dataset.skillindex):null;showSkill(skillActor,true);return;}if(b.dataset.pick!==undefined){chosenHero=Number(b.dataset.pick);$('#role-description').textContent='技能版 · '+SKILLS[chosenHero].name+'：'+SKILLS[chosenHero].text;modal.querySelectorAll('[data-pick]').forEach(x=>{const on=Number(x.dataset.pick)===chosenHero;x.setAttribute('aria-pressed',on);x.querySelector('small').textContent=on?'✓ 你已选择':'选择角色';});return;}if(b.dataset.mini){applyMini(b.dataset.mini);return;}const a=b.dataset.action;if(a==='tutorial'){startTutorial();return;}if(a==='credits'){openDialog('credits',`<h2>素材与制作</h2><p>角色特写：为本作单独生成的原创插画。镜头、字效、立体骰子与声音主题：本作制作。</p><p>骰子、筹码、纸牌录音：<a href="https://kenney.nl/assets/casino-audio" target="_blank" rel="noreferrer">Kenney Casino Audio</a>；粒子：<a href="https://kenney.nl/assets/particle-pack" target="_blank" rel="noreferrer">Kenney Particle Pack</a>。均为CC0，已随游戏保留许可。</p><p>演出参考：<a href="https://asia.sega.com/p3r/cn/" target="_blank" rel="noreferrer">Persona 3 Reload</a> 的战斗特写语言。游戏内没有使用其美术、音乐或角色素材。</p><button class="primary" data-action="close">回到牌桌</button>`);return;}if(a==='skill-confirm'){confirmSkill();return;}if(a==='skill-close'){closeDialog();render();if(['settled','finished'].includes(game.phase))showSummary();return;}if(a==='mini-pause'){showPause();return;}if(!a)return;if(a==='start'){const humans=Number($('#mode').value),rules=$('#ruleset').value,skills=$('#edition').value==='skills';preview=false;game=createGame(humans,Math.random,{rules,hero:chosenHero,skills});passiveRound=0;selected=0;modal.close();dialogType='';persist();render();showRules();}if(a==='resume'){preview=false;closeDialog();render();}if(a==='close'){if(preview){welcome();return;}closeDialog();render();}if(a==='next'){claimFeedback.clear();nextRound(game);selected=0;closeDialog();persist();render();scheduleBot();}if(a==='again'){closeDialog();welcome();}if(a==='restart-prompt')openDialog('restart',`<h2>重新开一桌？</h2><p>开始新牌局会替换当前进度。</p><button class="primary" data-action="again">选择新牌局</button><button class="quiet" data-action="close">继续当前牌局</button>`);});
modal.addEventListener('change',e=>{const k=e.target.dataset.pref;if(k){prefs[k]=e.target.checked;write(PREF,prefs);render();}});
modal.addEventListener('cancel',e=>{e.preventDefault();if(dialogType==='welcome')return;closeDialog();render();});
document.addEventListener('keydown',e=>{if(tutorial.active||cinema.active||modal.open||e.repeat)return;if(e.key==='Escape'){showPause();return;}if(!canAct())return;if(e.code==='Space'&&game.phase==='ready'){e.preventDefault();doRoll();}if(/^[1-6]$/.test(e.key)&&game.phase==='choose'&&game.roll.includes(Number(e.key))){selected=Number(e.key);render();}if(e.key==='Enter'&&game.phase==='choose'&&selected){e.preventDefault();commit();}if(e.key.toLowerCase()==='s'&&game.phase==='choose'){e.preventDefault();doSkip();}});
document.addEventListener('visibilitychange',()=>{if(tutorial.active)return;if(document.hidden){stopTimer();persist();if(cinema.active)return;busy=false;if(!modal.open&&!preview)showPause();}else if(cinema.active)return;else if(dialogType==='minigame')showMini();else scheduleBot();});window.addEventListener('pagehide',persist);welcome();
if(document.modelContext?.registerTool){const life=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'read_vegas_table',description:'Read visible game state, casino effects, dice and payouts without exposing undealt notes.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('No arguments accepted');return {round:game.round,phase:game.phase,turn:game.turn,players:game.players,roll:game.roll,tables:game.tables,paused:modal.open};}},{signal:life.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>life.abort(),{once:true});}
